async function load(append=false){if(noAccountsInWindow()){S.loading=false;render();return}const gen=++generation;const account=S.account,page=S.page;if(!pageSupported()||page==='mail'&&!can('mailRead')){S.loading=false;S.error='';S.messages=[];S.cursor=null;render();return}if(page==='mail'&&!visibleFolders().some(([id])=>id===S.folder))S.folder='inbox';if(page==='mail'&&!can('mailSearch'))S.query='';S.loading=true;S.error='';render();try{
 if(page==='settings')await cloudDrives.refresh();
 if(S.demo){if(page==='mail'){const xs=demo.messages.filter(m=>(S.folder==='starred'?m.starred:m.folder===S.folder)&&`${m.from} ${m.subject} ${m.body}`.toLowerCase().includes(S.query.toLowerCase()));S.messages=xs;S.cursor=null;}S.contacts=demo.contacts;S.events=demo.events;S.rules=demo.rules;}
 else if(page==='mail'){const v=await invoke('mail_list',{account,folder:S.folder,query:S.query,cursor:append?S.cursor:null});if(gen!==generation)return;S.messages=append?[...S.messages,...v.items]:v.items;S.cursor=v.cursor;}
 else if(page==='contacts'){const v=await invoke('contacts_list',{account});if(gen!==generation)return;S.contacts=v;}
 else if(page==='calendar'){const begin=new Date(S.month);begin.setDate(-6);const end=new Date(S.month.getFullYear(),S.month.getMonth()+1,8);const v=await invoke('calendar_list',{account,start:begin.toISOString(),end:end.toISOString()});if(gen!==generation)return;S.events=v;}
 else if(page==='rules'){const v=await invoke('rules',{account,sender:null,remove:null});if(gen!==generation)return;S.rules=v;}
 }catch(e){if(gen!==generation)return;S.error=String(e)}finally{if(gen===generation){S.loading=false;render()}}}
function modal(title,body){const m=$('#modal');m.classList.remove('manual-account-dialog');m.innerHTML=`${chrome.markup(true)}<div class="modal-head" data-tauri-drag-region><h2 data-tauri-drag-region>${title}</h2>${button('✕','close','quiet','aria-label="Close dialog"')}</div><div class="modal-body">${body}<div class="error" id="modal-error" role="alert"></div></div>`;if(!m.open)m.showModal()}
const field=(label,id,value='',type='text',extra='')=>`<label class="field">${label}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function compose(mode='new',recipient=''){cloudDrives.close();const m=S.messages.find(m=>m.id===S.selected);files=[];let to=recipient,cc='',subject='',body=pref().signature?'\n\n'+pref().signature:'';if(m&&mode!=='new'){subject=(mode==='forward'?'Fwd: ':'Re: ')+m.subject.replace(/^(Re|Fwd):\s*/i,'');if(mode!=='forward')to=email(m.from);if(mode==='reply-all')cc=m.to.split(',').map(email).filter(e=>e!==active().email&&e!==to).join(', ');body=(pref().signature?'\n\n'+pref().signature:'')+`\n\n${mode==='forward'?'---------- Forwarded message ----------':'On '+date(m.date)+', '+m.from+' wrote:'}\n${m.body}`;}modal('New message',`<div class="muted" style="margin-bottom:16px">From ${esc(active().email)}${S.demo?' · Demo mode':''}</div>${field('To','to',to,'text','list="contact-suggestions" placeholder="name@example.com"')}<datalist id="contact-suggestions">${S.contacts.filter(c=>c.email).map(c=>`<option value="${esc(c.email)}">${esc(c.name)}</option>`).join('')}</datalist><div class="two">${field('Cc','cc',cc)}${field('Bcc','bcc')}</div>${field('Subject','subject',subject)}<label class="field">Message<textarea aria-label="Message" id="body" spellcheck="true" lang="en" placeholder="Start something good…">${esc(body)}</textarea></label><div class="writing-toolbar">${button('✦ Rewrite with AI','ai-rewrite')}${button('Check writing','writing-check')}${button('Reply templates','reply-templates')}</div><div id="writing-panel"></div><label class="field">Attachments · up to ${active().provider==='outlook'?3:9} MB total<input id="files" type="file" multiple></label><div id="file-list"></div><div id="attachment-status" class="error" role="alert"></div>${button('☁ Attach from cloud','cloud-open','quiet cloud-open-button','aria-label="Attach from cloud"')}<div id="cloud-panel" class="cloud-picker" hidden></div><div class="modal-footer">${can('drafts')?button('Save draft','save-draft'):''}${button(S.demo?'Simulate send':'Send message','send','primary')}</div>`);$('#modal')._composeToken={};renderAttachments();if(!S.demo&&can('contacts')&&!S.contacts.length){const owner=S.account;invoke('contacts_list',{account:owner}).then(xs=>{if(S.account!==owner)return;S.contacts=xs;const el=$('#contact-suggestions');if(el)el.innerHTML=xs.filter(c=>c.email).map(c=>`<option value="${esc(c.email)}">${esc(c.name)}</option>`).join('')}).catch(()=>{});}}
function addAccount(){return accountSignIn.open()}
function contactForm(c={}){modal(c.id?'Edit contact':'New contact',`<div class="notice">${S.demo?'Changes affect demo data only.':'Changes are saved directly to '+(active().provider==='gmail'?'Google Contacts.':'Outlook contacts.')}</div>${!c.name&&c.email?`<div class="notice">Suggested name from email: ${esc(suggestName(c.email))}. Review before using. ${button('Use suggestion','suggest-contact-name','quiet',`data-name="${esc(suggestName(c.email))}"`)}</div>`:''}${field('Full name','contact-name',c.name)}${field('Email address','contact-email',c.email,'email')}${field('Phone number','contact-phone',c.phone,'tel')}<div class="modal-footer">${c.id?button('Delete contact','delete-contact','quiet danger'):''}${button('Cancel','close')}${button('Save contact','save-contact','primary')}</div>`);$('#modal')._contact=c;}
const localInput=d=>{d=new Date(d);d=new Date(d.getTime()-d.getTimezoneOffset()*60000);return d.toISOString().slice(0,16)};
function eventForm(e={}){const start=e.start||new Date(Date.now()+3600000).toISOString();modal(e.id?'Event details':'New event or meeting',`<div class="notice">${S.demo?'Demo calendar.':'Saved to your primary calendar. Adding attendees sends provider invitations.'} Times use your device’s local timezone.</div>${field('Title','event-title',e.title)}<div class="two">${field('Starts','event-start',localInput(start),'datetime-local')}${field('Ends','event-end',localInput(e.end||new Date(new Date(start).getTime()+3600000)),'datetime-local')}</div>${field('Location or meeting URL','event-location',e.location)}${e.id?'':field('Invite attendees · comma-separated emails','event-attendees',e.attendees)}<label class="field">Notes<textarea id="event-notes">${esc(e.description||'')}</textarea></label>${e.id&&!S.demo?'<p class="muted">Editing existing events is not enabled in this preview. Manage recurrence, attendees, RSVP, and meeting links in your provider.</p>':''}<div class="modal-footer">${e.id?button('Delete event','delete-event','quiet danger'):''}${button('Close','close')}${!e.id||S.demo?button('Save event','save-event','primary'):''}</div>`);$('#modal')._event=e;}
function ruleForm(sender=''){modal('Block sender with a provider rule',`<div class="notice">Future messages from this exact address will go to trash at your provider, even when Yas Mail is closed. This creates a mail rule; it does not edit the provider’s native blocked-sender list. Existing mail stays unchanged. Remove this rule later under Sender rules.</div>${field('Sender email address','rule-sender',sender,'email')}<div class="modal-footer">${button('Cancel','close')}${button('Create provider rule','save-rule','primary')}</div>`)}
async function modalTask(fn){const buttons=[...$('#modal').querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);$('#modal-error').textContent='';try{await fn()}catch(e){if($('#modal-error'))$('#modal-error').textContent=String(e);else fail(e)}finally{buttons.forEach(b=>b.disabled=b.dataset.finished==='yes')}}
