 if(a==='send'||a==='save-draft')return modalTask(async()=>{let sendResult;const draft={to:$('#to').value,cc:$('#cc').value,bcc:$('#bcc').value,subject:$('#subject').value,body:$('#body').value,files};if(!draft.to.trim()&&a==='send')throw 'Add a recipient.';if(S.demo){demo.messages.unshift({id:crypto.randomUUID(),from:active().email,to:draft.to,subject:draft.subject,body:draft.body,preview:draft.body,date:new Date().toISOString(),unread:false,starred:false,folder:a==='send'?'sent':'drafts',attachments:files.map(f=>({name:f.name}))});persist()}else sendResult=await invoke('mail_send',{account:S.account,draft,save:a==='save-draft'});if(a==='send'&&!S.demo&&pref().learnStyle)try{await invoke('style_remember',{account:S.account,body:draft.body})}catch{};$('#modal').close();toast(sendResult?.warning||(a==='send'?(S.demo?'Demo message added to Sent. No email was sent.':'Provider accepted your message for sending.'):'Draft saved to provider'));await load()});
