 if(['archive','trash','star','unstar','read','unread'].includes(a)&&m){const owner=S.account;try{if(S.demo){const x=demo.messages.find(x=>x.id===m.id);if(['archive','trash'].includes(a))x.folder=a;else if(a==='star'||a==='unstar')x.starred=a==='star';else x.unread=a==='unread';persist()}else await invoke('mail_action',{account:owner,id:m.id,action:a});if(S.account===owner)await load()}catch(e){fail(e)}return}
