 if(['prev-month','next-month','today'].includes(a)){S.month=a==='today'?new Date(new Date().getFullYear(),new Date().getMonth(),1):new Date(S.month.getFullYear(),S.month.getMonth()+(a==='next-month'?1:-1),1);return load()}
